# --- your code ---
import heapq


class PriceTracker:
    def __init__(self):
        self.price = {}                      # time -> its price after any correction
        self.last = 0                        # latest time seen
        self.high, self.low = [], []         # heaps of (-price, time) and (price, time)

    def update(self, time: int, price: int) -> None:
        self.price[time] = price
        self.last = max(self.last, time)
        heapq.heappush(self.high, (-price, time))   # older entries for this time stay, stale
        heapq.heappush(self.low, (price, time))

    def current(self) -> int:
        return self.price[self.last]

    def highest(self) -> int:
        while -self.high[0][0] != self.price[self.high[0][1]]:   # stale: corrected since
            heapq.heappop(self.high)
        return -self.high[0][0]

    def lowest(self) -> int:
        while self.low[0][0] != self.price[self.low[0][1]]:
            heapq.heappop(self.low)
        return self.low[0][0]


# --- provided: do not edit ---
def run_tracker(ops: list[list]) -> list:
    tracker = PriceTracker()
    return [getattr(tracker, name)(*args) for name, *args in ops]

