class PriceTracker:
    def __init__(self):
        self.price = {}                      # time -> its price after any correction
        self.last = 0

    def update(self, time: int, price: int) -> None:
        self.price[time] = price
        self.last = max(self.last, time)

    def current(self) -> int:
        return self.price[self.last]

    def highest(self) -> int:
        return max(self.price.values())      # a full scan on every query

    def lowest(self) -> int:
        return min(self.price.values())


def run_tracker(ops: list[list]) -> list:
    tracker = PriceTracker()
    return [getattr(tracker, name)(*args) for name, *args in ops]
